+        var tickColor = isDark ? 'rgba(255,255,255,0.45)' : 'rgba(0,0,0,0.42)';
+
+        var n = axes.length;
+        var x0 = ca.left;
+        var x1 = ca.right;
+        var y0 = ca.top;
+        var y1 = ca.bottom;
+        var step = (x1 - x0) / (n - 1);
+
+        ctx.save();
+        ctx.lineWidth = 1;
+        ctx.strokeStyle = axisColor;
+        ctx.fillStyle = tickColor;
+        ctx.font = '12px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
+
+        for (var i = 0; i < n; i++) {
+          var x = x0 + i * step;
+          ctx.beginPath();
+          ctx.moveTo(x, y0);
+          ctx.lineTo(x, y1);
+          ctx.stroke();
+
+          // ticks
+          var tickVals = [0, 25, 50, 75, 100];
+          for (var t = 0; t < tickVals.length; t++) {
+            var v = tickVals[t];
