+            ctx.beginPath();
+            ctx.moveTo(x - 4, y);
+            ctx.lineTo(x + 4, y);
+            ctx.stroke();
+
+            if (i === 0) {
+              ctx.textAlign = 'right';
+              ctx.textBaseline = 'middle';
+              ctx.fillText(String(v), x - 10, y);
+            }
+          }
+        }
+        ctx.restore();
+      },
+      afterDatasetsDraw: function(chart, args, opts) {
+        var ctx = chart.ctx;
+        var ca = chart.chartArea;
+        if (!ca) return;
+
+        var isDark = document.documentElement.classList.contains('theme-dark');
+        var labelColor = isDark ? 'rgba(255,255,255,0.86)' : 'rgba(15,23,42,0.9)';
+        var subtle = isDark ? 'rgba(255,255,255,0.45)' : 'rgba(15,23,42,0.45)';
+
+        var n = axes.length;
+        var x0 = ca.left;
+        var x1 = ca.right;
+        var y0 = ca.top;
+        var y1 = ca.bottom;
+        var step = (x1 - x0) / (n - 1);
+
+        ctx.save();
+        ctx.font = '12px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
+        ctx.textAlign = 'center';
+        ctx.textBaseline = 'top';
+        ctx.fillStyle = labelColor;
+        for (var i = 0; i < n; i++) {
+          var x = x0 + i * step;
+          var label = axes[i].label;
+          ctx.fillText(label, x, y1 + 10);
+        }
+
+        // small annotations for key trade-off axes
+        var pfeIndex = 1;
+        var pwrIndex = 2;
+        var xFuel = x0 + pfeIndex * step;
+        var xPower = x0 + pwrIndex * step;
+        ctx.fillStyle = subtle;
+        ctx.font = '11px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
+        ctx.fillText('Trade-off zone', (xFuel + xPower) / 2, y0 - 18);
+        ctx.restore();
+      }
+    };
+
+    function buildParallelChart() {
+      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
+
+      var isDark = document.documentElement.classList.contains('theme-dark');
+      var gridBorder = isDark ? 'rgba(255,255,255,0.10)' : 'rgba(0,0,0,0.10)';
+      var labelColor = isDark ? '#EDEDED' : '#0f172a';
+
+      var cars = rawCars.slice();
+      var leaders = computeAxisLeaders(cars);
+      var leaderSet = {};
+      axes.forEach(function(a) {
+        leaders[a.key].models.forEach(function(m) { leaderSet[m] = true; });
+      });
+
+      // Datasets: one per car, but grouped in legend by type.
+      var legendTypes = ['SUV', 'Sedan', 'Electric'];
+      var datasets = [];
+      legendTypes.forEach(function(t) {
+        datasets.push({
+          label: t,
+          data: [],
+          borderColor: 'rgba(0,0,0,0)',
+          pointRadius: 0,
+          borderWidth: 0
+        });
+      });
+
+      cars.forEach(function(c) {
+        var base = typePalette[c.type] || { stroke: '#94a3b8', fill: 'rgba(148,163,184,0.12)' };
+        var isLeader = !!leaderSet[c.model];
+        var alpha = isLeader ? 0.90 : 0.30;
+        var w = isLeader ? 2.8 : 1.2;
+
+        var series = axes.map(function(a, idx) {
+          return { x: idx, y: clamp(c[a.key], 0, 100) };
+        });
+
+        datasets.push({
+          label: c.model,
+          data: series,
+          borderColor: isLeader ? 'rgba(255,255,255,0.92)' : base.stroke,
+          backgroundColor: base.fill,
+          borderWidth: w,
+          pointRadius: isLeader ? 2.4 : 1.6,
+          pointHoverRadius: 4,
+          pointBackgroundColor: isLeader ? 'rgba(255,255,255,0.95)' : base.stroke,
+          pointBorderColor: isLeader ? 'rgba(0,0,0,' + (isDark ? '0.35' : '0.18') + ')' : 'rgba(0,0,0,0)',
+          pointBorderWidth: isLeader ? 1 : 0,
+          tension: 0,
+          parsing: false
+        });
+      });
+
+      var chart = ChartManager.safeInit('pcChart', {
+        type: 'line',
+        data: {
+          datasets: datasets
+        },
+        options: {
+          responsive: true,
+          maintainAspectRatio: false,
+          interaction: { mode: 'nearest', intersect: false },
+          scales: {
+            x: {
+              type: 'linear',
+              min: 0,
+              max: axes.length - 1,
+              grid: { display: false },
+              ticks: {
+                display: false
+              },
+              title: {
+                display: true,
+                text: 'Dimensions (left → right)'
+              }
+            },
+            y: {
+              min: 0,
+              max: 100,
+              grid: { color: gridBorder },
+              ticks: {
+                color: labelColor,
+                callback: function(v) { return v; }
+              },
+              title: {
+                display: true,
+                text: 'Score (0–100, higher is better)'
+              }
+            }
+          },
+          plugins: {
+            tooltip: {
+              enabled: true,
+              callbacks: {
+                title: function(items) {
+                  if (!items || !items.length) return '';
+                  var ds = items[0].dataset;
+                  return ds && ds.label ? ds.label : '';
+                },
+                label: function(ctx) {
+                  var idx = ctx.parsed.x;
+                  var axis = axes[idx];
+                  var val = ctx.parsed.y;
+                  if (!axis) return String(val);
+                  return axis.label + ': ' + val;
+                },
+                afterBody: function(items) {
+                  if (!items || !items.length) return '';
+                  var dsLabel = items[0].dataset.label;
+                  var found = null;
+                  for (var i = 0; i < rawCars.length; i++) {
+                    if (rawCars[i].model === dsLabel) { found = rawCars[i]; break; }
+                  }
+                  if (!found) return '';
+                  return 'Type: ' + found.type;
+                }
+              }
+            },
+            legend: {
+              display: true,
+              labels: {
+                color: labelColor,
+                filter: function(item, chartData) {
+                  // show legend only for 3 vehicle types and for leader annotation.
+                  return item.text === 'SUV' || item.text === 'Sedan' || item.text === 'Electric';
+                }
+              }
+            },
+            title: {
+              display: false
+            }
+          }
+        },
+        plugins: [ParallelCoordsPlugin]
+      });
+
+      // set a helpful description for screen readers
+      var canvas = document.getElementById('pcChart');
+      if (canvas) canvas.setAttribute('aria-description', 'Parallel coordinates across 7 axes. White lines highlight axis-leading models (ties possible).');
+
+      // Expose axis leaders in a data attribute for traceability
+      var chartEl = document.querySelector('.chart-shell');
+      if (chartEl) chartEl.setAttribute('data-axis-leaders', formatLeaderText(leaders));
+
+      return chart;
+    }
+
+    function onThemeChange() {
+      ChartManager.updateTheme();
+      buildParallelChart();
+    }
+
+    function loadData() {
+      return fetch('/app/benchmark/source_data.json')
+        .then(function(r) { return r.json(); })
+        .then(function(j) {
+          rawCars = (j && j.cars && j.cars.data) ? j.cars.data : [];
+          if (!rawCars.length) console.error('No car data loaded');
+        })
+        .catch(function(e) { console.error('Data load failed:', e); });
+    }
+
+    window.addEventListener('load', function() {
+      loadData().then(function() {
+        buildParallelChart();
+      });
+    });
+  </script>
+</body>
+</html>
+
*** End Patch
