const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');

(async () => {
  const htmlPath = path.resolve('output/viz.html');
  const outPath = path.resolve('output/result.png');
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox','--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  // Use a stable viewport for consistent rasterization
  await page.setViewport({ width: 1400, height: 900, deviceScaleFactor: 2 });

  const html = fs.readFileSync(htmlPath, 'utf8');
  await page.setContent(html, { waitUntil: 'domcontentloaded' });

  // Wait for Chart.js canvas to have pixels drawn.
  await page.waitForFunction(() => {
    const c = document.getElementById('pcChart');
    if (!c) return false;
    const ctx = c.getContext('2d');
    if (!ctx) return false;
    const w = c.width, h = c.height;
    if (!w || !h) return false;
    // sample a few pixels; if all transparent, chart likely not drawn yet
    const img = ctx.getImageData(Math.floor(w/2), Math.floor(h/2), 1, 1).data;
    return img[3] !== 0;
  }, { timeout: 15000 });

  // Ensure menu hidden in final export by adding a class override.
  await page.addStyleTag({ content: '.viz-menu{display:none !important;}' });

  // Tight crop: screenshot the main card.
  const el = await page.$('.chart-card');
  await el.screenshot({ path: outPath });

  await browser.close();
  console.log('Wrote', outPath);
})();
